WITH filtered_suppliers AS (SELECT * FROM suppliers WHERE country IN ('SG', 'US', 'TH') OR UPPER(TRIM(supplier_name)) = 'SIAM PARTS CO'), suppliers_stats AS (SELECT CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, MAX(rating) AS max_rating FROM filtered_suppliers GROUP BY CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END) SELECT rating_bucket, max_rating FROM suppliers_stats ORDER BY max_rating ASC, rating_bucket ASC LIMIT 5;
